-- ============================================================
-- 3. SAFETY GATE TRANSACTIONAL ASSERTION (EXACT MANIFEST IDs)
-- Validates exact 456 manifest UUIDs, NOT merely an order-number range.
-- Fails and automatically aborts transaction if any ID is missing.
-- ============================================================
CREATE TEMP TABLE IF NOT EXISTS _manifest_order_ids (
    order_id UUID PRIMARY KEY
) ON COMMIT DROP;


DO $$
DECLARE
    v_order_count INT;
    v_item_count INT;
BEGIN
    SELECT COUNT(*) INTO v_order_count 
    FROM orders 
    WHERE id IN (SELECT order_id FROM _manifest_order_ids);

    SELECT COUNT(*) INTO v_item_count 
    FROM order_items 
    WHERE order_id IN (SELECT order_id FROM _manifest_order_ids);

    IF v_order_count <> 456 THEN
        RAISE EXCEPTION 'Safety Gate Abort: Expected exactly 456 extension orders matching manifest UUIDs, but found %', v_order_count;
    END IF;

    IF v_item_count <> 1195 THEN
        RAISE EXCEPTION 'Safety Gate Abort: Expected exactly 1195 extension items matching manifest UUIDs, but found %', v_item_count;
    END IF;
END $$;

COMMIT;
